import{_ as a,c as r,o as t,ag as i}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"Practice: How to Approach Significant Refactoring","description":"","frontmatter":{},"headers":[],"relativePath":"practice/engineering/design/How_would_you_approach_significant_refactoring.md","filePath":"practice/engineering/design/How_would_you_approach_significant_refactoring.md"}'),n={name:"practice/engineering/design/How_would_you_approach_significant_refactoring.md"};function o(c,e,s,p,l,d){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="practice-how-to-approach-significant-refactoring" tabindex="-1">Practice: How to Approach Significant Refactoring <a class="header-anchor" href="#practice-how-to-approach-significant-refactoring" aria-label="Permalink to “Practice: How to Approach Significant Refactoring”">​</a></h1><p><strong>Learner status: outstanding.</strong> Author verification does not complete these criteria.</p><p>Prerequisite: <a href="./../../../senior_growth/EngX_Quality/How_would_you_approach_significant_refactoring.html">the worked lesson</a> and <a href="./../">the shared sequence</a>. Reuse the mapped existing project rather than build an application per note.</p><h2 id="scope-observable-acceptance-and-failure-cases" tabindex="-1">Scope, observable acceptance and failure cases <a class="header-anchor" href="#scope-observable-acceptance-and-failure-cases" aria-label="Permalink to “Scope, observable acceptance and failure cases”">​</a></h2><p><strong>Acceptance:</strong> explicit expected and old/new results match across boundary cases and generated strings; deliberately change the default/whitespace rule and confirm failure. Keep the public signature and previous consumers working, inspect errors/side effects for a real service, then remove obsolete duplication. A passing pure exercise is not a completed product refactor; learner migration/review/rollout evidence remains required.</p><p><strong>Acceptance:</strong> retain the assumptions/range, milestone evidence, alternatives, chosen trade-off, owner, follow-up and actual-versus-estimated record. Explain a plausible scope discovery and revise the estimate without concealing it. Tie the change to a delivery outcome and distinguish proposed benefits from measured results. The note supplies a complete planning example; executing the migration and collecting project delivery outcomes remain learner practice.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to “Evidence”">​</a></h2><p>Record source/runtime/tool versions, prerequisites and input, expected versus actual behavior, at least one failure→fix→retest, commands/exit status and retained artifacts. Distinguish local/mocked/source checks from native browser, external-service and deployment results. Screen-reader, zoom, real-device and cross-engine checks remain open unless actually performed. No remote push or paid-service activation.</p>',8)])])}const g=a(n,[["render",o]]);export{h as __pageData,g as default};
